// ByteStream is a generated byte stream over a provider-owned WebSocket wire:
// an io.ReadWriteCloser whose octets travel in binary messages, with no
// envelope and no in-band admission.
//
// The framework owns everything but the bytes: the upgrade carries the declared
// credentials, client identity and trace context exactly as a unary call
// would; the declared handshake, idle, operation and frame budgets bound the
// stream; the declared heartbeat is an RFC 6455 ping; and the call is measured
// once. Read returns io.EOF once the provider closes the stream normally and
// the typed terminal error otherwise. Read and Write may run in separate
// goroutines; neither is safe for concurrent use by several goroutines.
type ByteStream struct {
	wire    *providerWire
	pending []byte
}

// OpenByteStream opens the operation's provider-owned byte stream. It returns
// once the provider accepted the upgrade, or with the typed error the provider
// or the framework refused it with.
func OpenByteStream(ctx context.Context, client *Client, request *Request, operation Operation,
	errorMapper ...func(error) error) (*ByteStream, error) {
	wire, err := openProviderWire(ctx, client, request, operation, true, errorMapper)
	if err != nil {
		return nil, err
	}
	return &ByteStream{wire: wire}, nil
}

// Read reads octets the provider sent. Message boundaries carry no meaning on a
// byte stream, so one binary message may be read in several calls.
func (stream *ByteStream) Read(p []byte) (int, error) {
	if len(p) == 0 {
		return 0, nil
	}
	for len(stream.pending) == 0 {
		chunk, open := <-stream.wire.messages
		if !open {
			return 0, stream.wire.endOfStream()
		}
		stream.pending = chunk
	}
	n := copy(p, stream.pending)
	stream.pending = stream.pending[n:]
	return n, nil
}

// Write sends octets to the provider in binary messages no larger than the
// declared frame budget.
func (stream *ByteStream) Write(p []byte) (int, error) {
	written := 0
	for written < len(p) {
		size := len(p) - written
		if limit := stream.wire.maxFrameBytes(); limit > 0 && int64(size) > limit {
			size = int(limit)
		}
		if err := stream.wire.write(wsOpcodeBinary, p[written:written+size]); err != nil {
			return written, err
		}
		written += size
	}
	return written, nil
}

// Close ends the stream normally and releases the socket. It is idempotent.
func (stream *ByteStream) Close() error { return stream.wire.closeByCaller() }

// Done closes when the stream ends, whichever side ended it.
func (stream *ByteStream) Done() <-chan struct{} { return stream.wire.done }

// Err returns the sanitized terminal error, or nil for a normal end. Call it
// after Done.
func (stream *ByteStream) Err() error { return stream.wire.Err() }

// FrameStream is a generated stream of typed JSON frames over a provider-owned
// WebSocket wire: each message is one JSON value of TIn or TOut under the
// provider's declared subprotocol, with no first-party envelope. The provider's
// own protocol decides what the frames mean; the framework validates each one
// against the declared schema, bounds and measures the stream, and owns the
// socket.
type FrameStream[TIn, TOut any] struct {
	wire *providerWire
}

// OpenFrameStream opens the operation's provider-owned typed frame stream. It
// returns once the provider accepted the upgrade and negotiated the declared
// subprotocol.
func OpenFrameStream[TIn, TOut any](ctx context.Context, client *Client, request *Request, operation Operation,
	errorMapper ...func(error) error) (*FrameStream[TIn, TOut], error) {
	wire, err := openProviderWire(ctx, client, request, operation, false, errorMapper)
	if err != nil {
		return nil, err
	}
	return &FrameStream[TIn, TOut]{wire: wire}, nil
}

// Send validates one frame against the declared input schema and sends it as
// one text message.
func (stream *FrameStream[TIn, TOut]) Send(ctx context.Context, frame TIn) error {
	if err := ctx.Err(); err != nil {
		return normalizedCallError(ctx, err)
	}
	encoded, err := json.Marshal(frame)
	if err != nil {
		return errors.Wrap(err, CodeClientRequest)
	}
	projected, ok := projectJSON(encoded, stream.wire.operation.Contract.Messages.Input, stream.wire.schemas, nil, false)
	if !ok {
		return errors.New(CodeClientRequest, "service stream frame does not match the generated contract")
	}
	return stream.wire.write(wsOpcodeText, projected)
}

// Recv returns the next provider frame, io.EOF once the provider closed the
// stream normally, or the typed terminal error.
func (stream *FrameStream[TIn, TOut]) Recv(ctx context.Context) (TOut, error) {
	var zero TOut
	select {
	case payload, open := <-stream.wire.messages:
		if !open {
			return zero, stream.wire.endOfStream()
		}
		var frame TOut
		if err := json.Unmarshal(payload, &frame); err != nil {
			failure := errors.New(CodeClientResponse, "service stream frame cannot be decoded")
			stream.wire.terminate(failure)
			return zero, failure
		}
		return frame, nil
	case <-ctx.Done():
		return zero, normalizedCallError(ctx, ctx.Err())
	}
}

// Close ends the stream normally and releases the socket. It is idempotent.
func (stream *FrameStream[TIn, TOut]) Close() error { return stream.wire.closeByCaller() }

// Done closes when the stream ends, whichever side ended it.
func (stream *FrameStream[TIn, TOut]) Done() <-chan struct{} { return stream.wire.done }

// Err returns the sanitized terminal error, or nil for a normal end. Call it
// after Done.
func (stream *FrameStream[TIn, TOut]) Err() error { return stream.wire.Err() }

// providerWire is one admitted provider-owned socket. The reader goroutine
// owns the inbound half and the single terminal; the StreamSession owns the
// lifecycle, the budgets and the call measurement.
type providerWire struct {
	session   *StreamSession
	conn      *wsConn
	operation Operation
	schemas   map[string]clientcontract.Schema
	bytes     bool
	budgets   StreamBudgets

	messages chan []byte
	done     chan struct{}

	// callerClosed records a Close by the caller: the reader then ends the
	// stream as a normal end whatever the socket reports.
	callerClosed atomic.Bool
	// ended records the reader's terminal, so writes stop at it.
	ended atomic.Bool

	mu        sync.Mutex
	err       error
	failure   error
	closeOnce sync.Once
}

// openProviderWire runs everything up to and including admission: operation
// and transport checks, budgets, credentials, the upgrade request and its
// negotiated subprotocol.
func openProviderWire(ctx context.Context, client *Client, request *Request, operation Operation, bytes bool,
	errorMapper []func(error) error) (*providerWire, error) {
	runtime, httpTransport, callCtx, err := webSocketRuntime(ctx, client)
	if err != nil {
		return nil, err
	}
	ctx = callCtx
	if diagnostics := clientcontract.ValidateOperationForID(operation.ID, &operation.Contract,
		&runtime.descriptor.Contract); len(diagnostics) > 0 {
		return nil, errors.Newf(CodeClientConfig, "invalid generated operation contract: %s", diagnostics[0].String())
	}
	transport := clientcontract.OperationProviderWire(&operation.Contract)
	switch {
	case transport == nil:
		return nil, errors.Newf(CodeClientConfig, "operation %q declares no provider-owned websocket wire", operation.ID)
	case bytes && !transport.ByteStream():
		return nil, errors.Newf(CodeClientConfig, "operation %q is not a provider-owned byte stream", operation.ID)
	case !bytes && transport.ByteStream():
		return nil, errors.Newf(CodeClientConfig, "operation %q is a byte stream, not a typed frame stream", operation.ID)
	}

	var documentPolicy *clientcontract.ResiliencePolicy
	if runtime.descriptor.Contract.Defaults != nil {
		documentPolicy = runtime.descriptor.Contract.Defaults.Resilience
	}
	budgets := resolveWebSocketBudgets(documentPolicy, operation.Contract.Resilience)
	heartbeat := resolveWebSocketHeartbeat(documentPolicy, operation.Contract.Resilience)
	policy := resolvePolicy(documentPolicy, operation.Contract.Resilience, operation.Contract.Idempotency.Kind)

	// The upgrade request is the admission, so it carries what a unary call
	// carries: client identity, request identity, the declared credentials and
	// trace context. The credential-free set is kept so the send-point re-check
	// rebuilds from it rather than stacking a second credential.
	baseRequest, err := runtime.requestWithBindingHeaders(request, operation)
	if err != nil {
		return nil, err
	}
	baseRequest.Method = http.MethodGet
	if baseRequest.Path == "" {
		baseRequest.Path = transport.Path
	}
	baseRequest.OperationID = operation.ID
	if baseRequest.Headers == nil {
		baseRequest.Headers = make(http.Header)
	}
	if runtime.binding.ClientID != "" {
		baseRequest.Headers.Set("X-Client-Id", runtime.binding.ClientID)
	}
	if requestID := phttp.RequestIDFromContext(ctx); requestID != "" && baseRequest.Headers.Get("X-Request-ID") == "" {
		baseRequest.Headers.Set("X-Request-ID", requestID)
	}
	pristineHeaders := baseRequest.Headers.Clone()

	telemetry := currentServiceTelemetry()
	session, _ := newStreamSession(ctx, streamSessionConfig{
		ServiceID:   runtime.descriptor.Contract.Service.ID,
		OperationID: operation.ID,
		Protocol:    clientcontract.TransportWebSocket,
		Idempotency: operation.Contract.Idempotency.Kind,
		Budgets:     budgets,
		Breaker:     runtime.breaker(operation.ID, policy),
		Telemetry:   telemetry,
		Credentials: func(resolveCtx context.Context) (appliedCredentials, error) {
			scratch := &Request{Headers: pristineHeaders.Clone()}
			applied, err := runtime.applyCredentials(resolveCtx, scratch, operation.Contract.Security)
			if err != nil {
				return appliedCredentials{}, err
			}
			baseRequest.Headers = scratch.Headers
			return applied, nil
		},
		Invalidate: func(applied appliedCredentials) {
			runtime.invalidateServiceCredentials(applied.serviceCredentials)
		},
		MapError: func(err error) error { return mapStreamError(err, errorMapper) },
	})
	var release func()
	fail := func(err error) error {
		surfaced := session.Fail(err)
		session.Close() //nolint:errcheck // Close always returns nil; the terminal error is the return value
		if release != nil {
			release()
		}
		return surfaced
	}
	if err := session.config.Breaker.AllowRequest(); err != nil {
		return nil, fail(err)
	}
	tracked, trackErr := runtime.registry.TrackStream(session)
	if trackErr != nil {
		return nil, fail(trackErr)
	}
	release = tracked

	attemptCtx, finishAttempt := session.beginAttempt()
	applied, authErr := session.Credentials(attemptCtx)
	if authErr != nil {
		finishAttempt(ServiceAttemptResult{Code: serviceErrorCode(authErr), AuthDuration: session.AuthDuration()})
		return nil, fail(authErr)
	}
	if telemetry != nil {
		telemetry.InjectServiceContext(attemptCtx, baseRequest.Headers)
	}

	session.Dispatch()
	conn, dialErr := dialWebSocket(attemptCtx, webSocketDialRequest{
		URL:             webSocketURL(httpTransport, baseRequest, transport),
		Subprotocol:     transport.WebSocket.Subprotocol,
		Header:          baseRequest.Headers,
		Deadline:        session.handshakeDeadline(),
		MaxMessageBytes: budgets.MaxFrameBytes,
	})
	if dialErr != nil {
		return nil, fail(providerWireHandshakeFailure(runtime, operation, session, attemptCtx, finishAttempt, dialErr, applied))
	}
	finishAttempt(ServiceAttemptResult{StatusCode: http.StatusSwitchingProtocols, AuthDuration: session.AuthDuration()})
	session.Admit()
	conn.onActivity = session.touchIdle
	if err := conn.setReadDeadline(time.Time{}); err != nil {
		_ = conn.close() //nolint:errcheck // the terminal error is authoritative
		return nil, fail(errors.Wrap(err, CodeClientResponse))
	}

	wire := &providerWire{
		session:   session,
		conn:      conn,
		operation: operation,
		schemas:   runtime.descriptor.Schemas,
		bytes:     bytes,
		budgets:   budgets,
		messages:  make(chan []byte, max(budgets.MaxBufferedMessages, 1)),
		done:      make(chan struct{}),
	}
	// The socket is released as soon as the session ends — a caller context, the
	// declared operation duration, the idle budget or an application stop — so
	// the blocked reader wakes up and records the terminal.
	go func() {
		<-session.Context().Done()
		_ = conn.close() //nolint:errcheck // the reader records the terminal
	}()
	startProviderWireHeartbeat(wire, heartbeat)
	go wire.read(release)
	return wire, nil
}

// providerWireHandshakeFailure projects a refused or failed upgrade. An
// ordinary HTTP refusal is decoded through the operation's declared errors,
// exactly like a unary non-2xx answer.
func providerWireHandshakeFailure(runtime *serviceRuntime, operation Operation, session *StreamSession,
	attemptCtx context.Context, finishAttempt func(ServiceAttemptResult), dialErr error, applied appliedCredentials) error {
	var rejection *webSocketHandshakeRejection
	if stderrors.As(dialErr, &rejection) {
		if rejection.StatusCode == http.StatusUnauthorized || rejection.StatusCode == http.StatusForbidden {
			session.invalidateCredentials()
		}
		remote := decodeRemoteError(runtime.identity(operation),
			&Response{StatusCode: rejection.StatusCode, Headers: rejection.Header, Body: rejection.Body},
			operation.Contract.Errors, runtime.descriptor.Schemas, applied.secrets, runtime.binding.CarryRemoteMessage)
		finishAttempt(ServiceAttemptResult{StatusCode: rejection.StatusCode, Code: serviceErrorCode(remote),
			AuthDuration: session.AuthDuration()})
		return remote
	}
	var failure error
	switch {
	case stderrors.Is(dialErr, errWebSocketNotNegotiated):
		// The provider serves WebSocket at this path, but not the declared wire.
		failure = errors.New(CodeClientResponse, "service did not negotiate the declared websocket subprotocol")
	case webSocketHandshakeExpired(dialErr) && session.Context().Err() == nil:
		failure = errors.New(CodeClientDeadline, "service stream handshake deadline exceeded")
	default:
		failure = normalizedCallError(attemptCtx, dialErr)
	}
	finishAttempt(ServiceAttemptResult{Code: serviceErrorCode(failure), AuthDuration: session.AuthDuration()})
	return failure
}

// providerWireEnd is how the inbound half ended: the typed terminal the caller
// reads, nil for a normal end, and the close code the provider is told when it
// still listens. The code never reaches the caller and the error never reaches
// the wire.
type providerWireEnd struct {
	err       error
	closeCode int
}

// read delivers provider messages until the stream ends, then records the
// single terminal, tells the provider why when it still listens, and releases
// everything the stream held.
func (wire *providerWire) read(release func()) {
	end := wire.readUntilEnd()
	wire.ended.Store(true)
	wire.mu.Lock()
	if wire.failure != nil {
		// A failure the caller observed — a frame its type cannot hold — is the
		// reason this stream stopped, whatever the socket reported after it.
		end = providerWireEnd{err: wire.failure, closeCode: wsCloseUnsupportedData}
	}
	wire.mu.Unlock()
	close(wire.messages)
	if end.err == nil || wire.callerClosed.Load() {
		wire.session.Complete()
	} else {
		wire.setErr(wire.session.Fail(end.err))
	}
	wire.shutdown(end)
	wire.session.Close() //nolint:errcheck // Close always returns nil; the terminal is recorded above
	if release != nil {
		release()
	}
	close(wire.done)
}

// readUntilEnd is the inbound half. A normal end — the provider's normal close
// or a Close by the caller — carries no error.
func (wire *providerWire) readUntilEnd() providerWireEnd {
	want := wsOpcodeText
	if wire.bytes {
		want = wsOpcodeBinary
	}
	for {
		opcode, payload, err := wire.conn.readMessage()
		if err != nil {
			return wire.readFailure(err)
		}
		if opcode != want {
			return providerWireEnd{
				err:       errors.New(CodeClientResponse, "service sent a websocket message type the declared wire does not carry"),
				closeCode: wsCloseUnsupportedData,
			}
		}
		if !wire.bytes {
			if !utf8.Valid(payload) {
				return providerWireEnd{
					err:       errors.New(CodeClientResponse, "service websocket text frame is not valid UTF-8"),
					closeCode: wsCloseInvalidPayload,
				}
			}
			projected, ok := projectResponseJSON(payload, wire.operation.Contract.Messages.Output, wire.schemas, nil, false)
			if !ok {
				return providerWireEnd{
					err:       errors.New(CodeClientResponse, "service stream frame does not match the generated contract"),
					closeCode: wsCloseInvalidPayload,
				}
			}
			payload = projected
		}
		wire.session.Activate()
		select {
		case wire.messages <- payload:
		case <-wire.session.Context().Done():
			return wire.readFailure(wire.session.Context().Err())
		case <-wire.session.idleExpired():
			return providerWireEnd{
				err: errors.New(CodeClientDeadline, "service stream idle timeout"), closeCode: wsCloseGoingAway,
			}
		}
	}
}

// readFailure projects why the socket stopped delivering into the typed
// terminal the caller reads, and the close code the provider is told.
func (wire *providerWire) readFailure(err error) providerWireEnd {
	if wire.callerClosed.Load() {
		return providerWireEnd{}
	}
	var closed *wsCloseError
	if stderrors.As(err, &closed) && closed.Code == wsCloseNormal {
		return providerWireEnd{}
	}
	if wire.session.idleBudgetExpired() {
		return providerWireEnd{
			err: errors.New(CodeClientDeadline, "service stream idle timeout"), closeCode: wsCloseGoingAway,
		}
	}
	if sessionCtx := wire.session.Context(); sessionCtx.Err() != nil {
		return providerWireEnd{err: normalizedCallError(sessionCtx, err), closeCode: wsCloseGoingAway}
	}
	var protocolErr *wsProtocolError
	if stderrors.As(err, &protocolErr) {
		return providerWireEnd{
			err:       errors.Newf(CodeClientResponse, "service websocket framing is invalid: %s", protocolErr.message),
			closeCode: protocolErr.closeCode,
		}
	}
	if stderrors.As(err, &closed) {
		// The provider already closed: there is nobody left to tell.
		return providerWireEnd{
			err: errors.Newf(CodeClientResponse, "service closed the websocket with code %d", closed.Code),
		}
	}
	return providerWireEnd{err: errors.New(CodeClientResponse, "service stream connection ended")}
}

// write sends one message unless the stream already ended.
func (wire *providerWire) write(opcode wsOpcode, payload []byte) error {
	if wire.ended.Load() || wire.callerClosed.Load() {
		if err := wire.Err(); err != nil {
			return err
		}
		return errors.New(CodeClientRequest, "service stream is closed")
	}
	var err error
	if opcode == wsOpcodeBinary {
		err = wire.conn.writeBinary(payload)
	} else {
		err = wire.conn.writeText(payload)
	}
	if err == nil {
		return nil
	}
	var protocolErr *wsProtocolError
	if stderrors.As(err, &protocolErr) {
		return errors.Newf(CodeClientRequest, "service stream message is invalid: %s", protocolErr.message)
	}
	if terminal := wire.Err(); terminal != nil {
		return terminal
	}
	return errors.New(CodeClientRequest, "service stream write failed")
}

// maxFrameBytes is the declared bound on one message.
func (wire *providerWire) maxFrameBytes() int64 { return wire.budgets.MaxFrameBytes }

// closeByCaller ends the stream normally from the caller's side: one close
// frame, then the session stops and the reader records the normal end.
func (wire *providerWire) closeByCaller() error {
	wire.closeOnce.Do(func() {
		if !wire.ended.Load() {
			wire.callerClosed.Store(true)
			_ = wire.conn.setWriteDeadline(time.Now().Add(webSocketCloseWriteBudget)) //nolint:errcheck // a closing socket reports through the terminal
			_ = wire.conn.writeClose(wsCloseNormal, "")                               //nolint:errcheck // the peer may already be gone
		}
		wire.session.Cancel()
	})
	<-wire.done
	return nil
}

// terminate ends the stream from the caller's side with a failure the caller
// observed, such as a frame its type cannot hold.
func (wire *providerWire) terminate(failure error) {
	wire.mu.Lock()
	if wire.failure == nil {
		wire.failure = failure
	}
	wire.mu.Unlock()
	wire.session.Cancel()
}

// shutdown tells the provider why the stream ended when it still listens, then
// releases the socket. The close reason is framework text only.
func (wire *providerWire) shutdown(end providerWireEnd) {
	if end.closeCode != 0 && !wire.callerClosed.Load() {
		reason := "client_error"
		if end.closeCode == wsCloseGoingAway {
			reason = "client_withdrew"
		}
		_ = wire.conn.setWriteDeadline(time.Now().Add(webSocketCloseWriteBudget)) //nolint:errcheck // a closing socket reports through the terminal
		_ = wire.conn.writeClose(end.closeCode, reason)                           //nolint:errcheck // the terminal error is authoritative
	}
	_ = wire.conn.close() //nolint:errcheck // the terminal error is authoritative
}

// endOfStream is what a read returns once the messages are drained: io.EOF for
// a normal end, the typed terminal otherwise.
func (wire *providerWire) endOfStream() error {
	<-wire.done
	if err := wire.Err(); err != nil {
		return err
	}
	if wire.callerClosed.Load() {
		return errors.New(CodeClientRequest, "service stream is closed")
	}
	return io.EOF
}

// Err returns the sanitized terminal error, or nil.
func (wire *providerWire) Err() error {
	wire.mu.Lock()
	defer wire.mu.Unlock()
	return wire.err
}

func (wire *providerWire) setErr(err error) {
	wire.mu.Lock()
	if wire.err == nil {
		wire.err = err
	}
	wire.mu.Unlock()
}

// startProviderWireHeartbeat sends an RFC 6455 ping at the declared cadence.
// The provider's pong refreshes the idle budget like any other frame. A
// cadence nobody declared is not sent.
func startProviderWireHeartbeat(wire *providerWire, heartbeat time.Duration) {
	if heartbeat <= 0 {
		return
	}
	go func() {
		ticker := time.NewTicker(heartbeat)
		defer ticker.Stop()
		for {
			select {
			case <-wire.done:
				return
			case <-ticker.C:
				if err := wire.conn.writeControl(wsOpcodePing, nil); err != nil {
					return
				}
			}
		}
	}()
}
